<script setup>
import { ref,onMounted,onBeforeUnmount } from 'vue';
import { ccCall } from '../../api/cc';
import CCDataTable from './CCDataTable.vue';
const emit=defineEmits(['open']);const days=ref(30),closed=ref(false),statuses=ref([]),owner=ref(''),data=ref(null),rows=ref([]),busy=ref(false),error=ref('');let generation=0,controller;
const columns=[{key:'lead_name',label:'Client'},{key:'name',label:'Lead'},{key:'ph4',label:'Phone',value:r=>'••••'+r.ph4},{key:'owner',label:'Agent'},{key:'sub',label:'Last outcome'},{key:'last',label:'Last call'},{key:'next',label:'Next follow-up'},{key:'branch',label:'Branch'}];
async function load(more=false){const token=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';if(!more){rows.value=[];data.value=null;}try{const result=await ccCall('life_cc_nofu_v1',{days:days.value,closed:+closed.value,statuses:JSON.stringify(statuses.value),owner:owner.value,start:more?rows.value.length:0,limit:200},controller.signal);if(token!==generation)return;data.value=result;rows.value=more?[...rows.value,...result.rows]:result.rows;}catch(e){if(token===generation&&e.name!=='AbortError')error.value=e.message;}finally{if(token===generation)busy.value=false;}}
onMounted(()=>load());onBeforeUnmount(()=>{generation++;controller?.abort();});
</script>
<template><section class="cc-card"><h2>No follow-up since N days</h2><form class="cc-filters" @submit.prevent="load()"><label>Days since last call<input v-model.number="days" type="number" min="1" max="7300" required></label><label><input v-model="closed" type="checkbox"> Include closed leads</label><label>Agent<select v-model="owner"><option value="">All permitted agents</option><option v-for="a in data?.agents||[]" :key="a.agent" :value="a.agent">{{a.agent}} ({{a.n}})</option></select></label><button :disabled="busy">Apply</button></form><div class="cc-filters"><button v-for="bucket in data?.buckets||[]" :key="bucket.days" :aria-pressed="days===bucket.days" @click="days=bucket.days;load()">{{bucket.days}}d · {{bucket.n}}</button></div><div class="cc-filters"><label v-for="s in data?.statuses||[]" :key="s.status"><input v-model="statuses" type="checkbox" :value="s.status">{{s.status}} ({{s.n}})</label><button v-if="data?.statuses?.length" :disabled="busy" @click="load()">Filter outcomes</button></div><p v-if="error" class="cc-error" role="alert">{{error}} <button @click="load()">Retry</button></p><p v-if="data">Showing {{rows.length}} of {{data.total}} leads · numbers masked</p><CCDataTable :columns="columns" :rows="rows" :busy="busy"><template #actions="{row}"><button @click="emit('open',row.name)">Open lead</button></template></CCDataTable><button v-if="data&&rows.length<data.total" :disabled="busy" @click="load(true)">{{busy?'Loading…':'Load next 200'}}</button></section></template>
